# Fotos de producto en la web publica de Chivato (/web).
# Toca solo el servicio chivato-codigos (server.py), NO bot.py. Hace copia y comprueba antes de cambiar nada.
import base64, os, re, shutil, subprocess, sys, time, urllib.request
DIR = "/opt/chivato/codigos"
SRV = os.path.join(DIR, "server.py")
WEBF = os.path.join(DIR, "web.html")
HOST = "chivato-ofertas.duckdns.org"
MARCA = "# --- WEBFOTOS1 ---"
BLOQUE = base64.b64decode("").decode()
WEB = base64.b64decode("")
sh = lambda c: subprocess.run(c, shell=True, capture_output=True, text=True)
sello = time.strftime("%Y%m%d-%H%M%S")

print("== 1/3 Servicio de fotos")
src = open(SRV, encoding="utf-8").read()
if MARCA in src:
    print("ya estaba")
else:
    ent = list(re.finditer(r'(?m)^if __name__ == ["\']__main__["\']:', src))
    get = list(re.finditer(r'(?m)^(\s+)ruta = urllib\.parse\.urlparse\(self\.path\)\.path\.rstrip\("/"\)\n(?=\s+if ruta == "/web":)', src))
    if len(ent) != 1 or len(get) != 1:
        print("ABORTO: no reconozco server.py (%d/%d). No toco nada." % (len(ent), len(get))); sys.exit(1)
    ind = get[0].group(1)
    gancho = ind + 'if ruta.startswith("/web/foto/"):\n' + ind + '    return _wf_responder(self, ruta)\n'
    nuevo = src[:get[0].end()] + gancho + src[get[0].end():ent[0].start()] + BLOQUE + "\n" + src[ent[0].start():]
    try:
        compile(nuevo, SRV, "exec")
    except SyntaxError as e:
        print("ABORTO: no compila:", e); sys.exit(1)
    shutil.copy(SRV, SRV + ".bak-" + sello)
    open(SRV, "w", encoding="utf-8").write(nuevo)
    sh("systemctl restart chivato-codigos"); time.sleep(3)
    print("ok (copia en %s.bak-%s)" % (SRV, sello))

print("== 2/3 Web con fotos")
if os.path.exists(WEBF):
    shutil.copy(WEBF, WEBF + ".bak-" + sello)
open(WEBF, "wb").write(WEB)
print("ok")

print("== 3/3 Comprobacion")
import json
ok = True
try:
    j = json.loads(urllib.request.urlopen("http://127.0.0.1:8766/api/codigos", timeout=10).read())
    print("OK    servicio codigos")
except Exception as e:
    ok = False; print("FALLA servicio codigos", e); print(sh("journalctl -u chivato-codigos -n 15 --no-pager -o cat").stdout)
try:
    ofs = json.loads(urllib.request.urlopen("https://%s/api/ofertas" % HOST, timeout=15).read()).get("ofertas") or []
    asins = [o["asin"] for o in ofs if re.fullmatch(r"[A-Z0-9]{10}", str(o.get("asin", "")))][:3]
    bien = 0
    for a in asins:
        try:
            d = urllib.request.urlopen("https://%s/web/foto/%s" % (HOST, a), timeout=60).read(); bien += 1
            print("OK    foto", a, len(d), "bytes")
        except Exception as e:
            print("--    foto", a, "sin foto (saldra el icono)", e)
    if asins and not bien:
        ok = False
except Exception as e:
    ok = False; print("FALLA ofertas", e)
print("\nLISTO: abre https://%s/web (la 1a vez las fotos tardan unos segundos en cargar)" % HOST if ok else "\nHAY ALGUN FALLO: manda captura")
print("Deshacer: cp %s.bak-%s %s && systemctl restart chivato-codigos" % (SRV, sello, SRV))
